p='src/statement.mjs'
s=open(p).read()
rep=[
("""    quantity: `${formatQuantity(line.quantity)} ${line.unit}`,""","""    quantity: formatQuantity(line.quantity),
    unit: line.unit,"""),
("""  // Columns: label, quantity (right-aligned), amount (right-aligned).
  const amountHeading = "Amount";
  const quantityHeading = "Quantity";""","""  // Columns: label, quantity (right-aligned) and unit, amount (right-aligned).
  const amountHeading = "Amount";
  const quantityHeading = "Quantity";
  const unitWidth = Math.max(0, ...charges.map((row) => row.unit.length));"""),
("""  const quantityWidth = Math.max(quantityHeading.length, ...charges.map((row) => row.quantity.length));""",
"""  const numberWidth = Math.max(0, ...charges.map((row) => row.quantity.length));
  const quantityWidth = Math.max(quantityHeading.length, numberWidth + 1 + unitWidth);
  const quantityText = (charge) =>
    `${charge.quantity.padStart(numberWidth)} ${charge.unit}`.padEnd(quantityWidth);"""),
("""    Math.max("Total charges".length, ...charges.map((row) => row.label.length)),""",
"""    Math.max("Service".length, ...charges.map((row) => row.label.length)),"""),
("""  out.push(...wrap(`Usage statement for ${formatPeriod(data.period)}`, MAX_WIDTH));
  out.push("");
  out.push(...wrap(`Customer  ${data.customer}`, MAX_WIDTH));
  out.push(...wrap(`Account   ${data.account}`, MAX_WIDTH));
  out.push(...wrap(`Amounts in ${data.currency}`, MAX_WIDTH));
  out.push("");
  out.push(...row("Charges", quantityHeading, amountHeading));
  for (const charge of charges) out.push(...row(charge.label, charge.quantity, charge.amount));""",
"""  out.push(...wrap(`${data.customer} usage statement, ${formatPeriod(data.period)}`, MAX_WIDTH));
  out.push(...wrap(`Account ${data.account}. Amounts in ${data.currency}.`, MAX_WIDTH));
  out.push("");
  out.push("Charges");
  out.push(...row("Service", quantityHeading.padEnd(quantityWidth), amountHeading));
  for (const charge of charges) out.push(...row(charge.label, quantityText(charge), charge.amount));"""),
]
for a,b in rep:
    assert a in s, a
    s=s.replace(a,b)
open(p,'w').write(s)
EOF
npm run -s capture && sed -n '/```text/,$p' captures/CAPTURE.md && npm test 2>&1 | tail -9

